aneDialog(frame)), createMenuItem(&#34;纺纱分厂工资信息&#34;, &#39;F&#39;, null), null, createMenuItem(&#34;人事部职工信息&#34;, &#39;R&#39;, null), createMenuItem(&#34;财务部职工信息&#34;, &#39;C&#39;, null), createMenuItem(&#34;材料可职工信息&#34;, 0, null), createMenuItem(&#34;销售科职工信息&#34;, 0, null), createMenuItem(&#34;成品车间职工信息&#34;, 0, null)); // 中层干部信息系统菜单 JMenu menu2 = new JMenu(&#34;中层干部信息系统&#34;); menu2.setMnemonic(&#39;C&#39;); // 创建菜单项 JMenuItem factoryManagerItem = createMenuItem(&#34;分厂厂长信息&#34;, 0, null); JMenuItem departmentManagerItem = createMenuItem(&#34;部门经理信息&#34;, 0, null); // 使用 disableManagerMenu 方法处理禁用逻辑 factoryManagerItem.addActionListener(e -&gt; disableManagerMenu(departmentManagerItem)); // 添加到 menu2 menu2.add(factoryManagerItem); menu2.add(departmentManagerItem); // 工资系统菜单（复选框菜单） JMenu menu3 = new JMenu(&#34;工资系统&#34;); menu3.setMnemonic(&#39;G&#39;); menu3.add(createCheckBoxMenuItem(&#34;职工工资信息&#34;, false)); menu3.add(createCheckBoxMenuItem(&#34;领导工资信息&#34;, false)); // 查询系统菜单（单选框菜单） JMenu menu4 = new JMenu(&#34;查询系统&#34;); menu4.setMnemonic(&#39;F&#39;); ButtonGroup group = new ButtonGroup(); JRadioButtonMenuItem searchByName = createRadioButtonMenuItem(&#34;按照姓名查询&#34;, group, true); JRadioButtonMenuItem searchByID = createRadioButtonMenuItem(&#34;按照工号查询&#34;, group, false); menu4.add(searchByName); menu4.add(searchByID); // 登录系统菜单 JMenu menu5 = createMenu(&#34;登录系统&#34;, &#39;D&#39;, createMenuItem(&#34;添加登录用户名&#34;, 0, null)); // 帮助系统菜单 JMenu menu6 = createMenu(&#34;帮助系统&#34;, &#39;H&#39;, createMenuItem(&#34;版本信息&#34;, 0, null), createMenuItem(&#34;帮助信息&#34;, 0, null)); // 添加菜单到菜单栏 menuBar.add(menu1); menuBar.add(menu2); menuBar.add(menu3); menuBar.add(menu4); menuBar.add(menu5); menuBar.add(menu6); return menuBar; } // 禁用菜单项的方法 private static void disableManagerMenu(JMenuItem menuItem) { if (menuItem != null) { menuItem.setEnabled(false); // 禁用菜单项 } } private static JPopupMenu createPopupMenu(JFrame frame) { JPopupMenu popupMenu = new JPopupMenu(); JMenuItem infoItem = new JMenuItem(&#34;显示信息&#34;); infoItem.addActionListener(e -&gt; JOptionPane.showMessageDialog(frame, &#34;右键菜单：显示信息&#34;)); popupMenu.add(infoItem); JMenuItem exitItem = new JMenuItem(&#34;退出&#34;); exitItem.addActionListener(e -&gt; System.exit(0)); popupMenu.add(exitItem); return popupMenu; } private static JCheckBoxMenuItem createCheckBoxMenuItem(String title, boolean selected) { JCheckBoxMenuItem item = new JCheckBoxMenuItem(title); item.setSelected(selected); return item; } private static JRadioButtonMenuItem createRadioButtonMenuItem(String title, ButtonGroup group, boolean selected) { JRadioButtonMenuItem item = new JRadioButtonMenuItem(title, selected); group.add(item); return item; } private static JMenu createMenu(String title, char mnemonic, Object... items) { JMenu menu = new JMenu(title); menu.setMnemonic(mnemonic); for (Object item : items) { if (item == null) { menu.addSeparator(); } else if (item instanceof JMenuItem) { menu.add((JMenuItem) item); } } return menu; } private static JMenuItem createMenuItem(String title, int acceleratorKey, ActionListener action) { JMenuItem item = new JMenuItem(title); if (acceleratorKey != 0) { item.setAccelerator(KeyStroke.getKeyStroke(acceleratorKey, InputEvent.CTRL_DOWN_MASK)); } if (action != null) { item.addActionListener(action); } return item; } private static void showTabbedPaneDialog(JFrame parentFrame) { JDialog dialog = new JDialog(parentFrame, &#34;磨砂分厂职工信息&#34;, true); dialog.setSize(700, 400); Toolkit toolkit = Toolkit.getDefaultToolkit(); Dimension screenSize = toolkit.getScreenSize(); dialog.setLocation(screenSize.width / 2 - dialog.getWidth() / 2, screenSize.height / 2 - dialog.getHeight() / 2); JTabbedPane tabbedPane = new JTabbedPane(); for (int i = 1; i &lt;= 5; i++) { JPanel panel = createWorkshopPanel(i); tabbedPane.addTab(&#34;车间 &#34; + i + &#34; 信息&#34;, panel); } dialog.add(tabbedPane); dialog.setVisible(true); } private static JPanel createWorkshopPanel(int workshopNumber) { JPanel panel = new JPanel(new java.awt.GridBagLayout()); GridBagConstraints gbc = new GridBagConstraints(); gbc.insets = new Insets(5, 5, 5, 5); // 设置组件间的间距 gbc.fill = GridBagConstraints.HORIZONTAL; // 添加基本信息的标题 JLabel titleLabel = new JLabel(&#34; 基本信息&#34;, JLabel.CENTER); titleLabel.setFont(new Font(&#34;Serif&#34;, Font.BOLD, 16)); titleLabel.setBorder(BorderFactory.createEmptyBorder(10, 0, 50, 0)); gbc.gridx = 0; gbc.gridy = 0; gbc.gridwidth = 4; // 跨两列 panel.add(titleLabel, gbc); // 恢复单元格宽度 gbc.gridwidth = 1; // 字段标签与输入框 String[] labels = { &#34;姓名&#34;, &#34;出生年月&#34;, &#34;工号&#34;, &#34;家庭住址&#34;, &#34;性别&#34;, &#34;车间&#34;, &#34;年龄&#34;, &#34;职位&#34; }; for (int i = 0; i &lt; labels.length / 2; i++) { // 添加标签 JLabel label1 = new JLabel(labels[i] + &#34;：&#34;); gbc.gridx = 0; gbc.gridy = i + 1; panel.add(label1, gbc); // 添加文本框 JTextField textField1 = new JTextField(20); gbc.gridx = 1; gbc.gridy = i + 1; panel.add(textField1, gbc); // 添加标签 JLabel label2 = new JLabel(labels[i] + &#34;：&#34;); gbc.gridx = 2; gbc.gridy = i + 1; panel.add(label2, gbc); // 添加文本框 JTextField textField2 = new JTextField(20); gbc.gridx = 3; gbc.gridy = i + 1; panel.add(textField2, gbc); } return panel; } } 总结 本章重点，文本组件、窗口组件、对话框组件、菜单组件、工具条组件。这么多内容一次记住很难，不过通过例子来理解，就比较容易了。
